"""Reproducible English result and formula appendix, with complete local evidence."""
from common import *
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak,Image,KeepTogether
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib import colors
from reportlab.lib.enums import TA_LEFT

styles=getSampleStyleSheet();styles.add(ParagraphStyle(name='SmallText',fontName='Helvetica',fontSize=8,leading=10,spaceAfter=4));styles.add(ParagraphStyle(name='TinyText',fontName='Helvetica',fontSize=7,leading=8.5));styles.add(ParagraphStyle(name='FormulaHeading',fontName='Helvetica-Bold',fontSize=10,leading=12,spaceBefore=6,spaceAfter=3))
def p(text,style='SmallText'):return Paragraph(escape(str(text)),styles[style])
def tab(rows,widths):
    result=Table([[p(v,'TinyText') for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
    result.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e4eef3')),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,colors.gray),('BOTTOMPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),5),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f7f9fa')])]))
    return result
def page(canvas,doc):
    canvas.setFont('Helvetica',8);canvas.drawString(42,25,'Logic-Guided Temporal Representations | next_round_20261116_v1');canvas.drawRightString(553,25,str(doc.page))
def main():
    out=HERE/'results';story=[]
    story.extend([p('Fixed-origin experiments and formula audit','Title'),p('Observation event 10; raw window 10; first purchase in the next 10 recognized events. All main comparisons retain the frozen basis chosen before new test evaluation.','BodyText'),Spacer(1,10)])
    scores=pd.read_csv(out/'neural_mean_sample_sd.csv')
    rows=[['Dataset','Condition','MCC mean +/- SD','AP mean +/- SD']]
    from report import NAMES
    order={d:i for i,d in enumerate(['Coveo','Electronics','Cosmetics'])};co={c:i for i,c in enumerate(['raw','counts','transitions','ltlf'])}
    scores=scores.assign(ds_order=scores.dataset.map(order),c_order=scores.condition.map(co)).sort_values(['ds_order','c_order'])
    for r in scores.itertuples():rows.append([r.dataset,NAMES[r.condition],f'{r.MCC_mean:.4f} +/- {r.MCC_std:.4f}',f'{r.AP_mean:.4f} +/- {r.AP_std:.4f}'])
    story.extend([p('Table S1. Matched neural comparison','Heading2'),tab(rows,[75,190,120,120]),p('Three training seeds (42, 43, 44), sample SD. Raw encoders follow the dataset-specific implementations, with train-prefix-only vocabularies, a common 64-wide classification head, 25 epochs maximum, patience 5, validation AP checkpoint selection, and a validation-MCC threshold grid. These settings are shared within this new comparison; they differ from some historical full-observation runs.')])
    story.extend([Image(str(out/'neural_paired_differences.png'),width=505,height=224),p('Figure S1. Learned LTLf minus Counts or Transitions. Fixed seed-42 models and thresholds; 1,500 paired bootstrap resamples. Coveo resamples sessions; Electronics and Cosmetics resample users. Intervals are percentile 95% CIs, not training-seed SDs. Intervals crossing zero do not establish equivalence.'),PageBreak()])
    rows=[['Dataset','Condition','MCC','AP']]
    linear=pd.read_csv(out/'linear_metrics.csv')
    for r in linear.itertuples():rows.append([r.dataset,NAMES[r.condition],f'{r.MCC:.4f}',f'{r.AP:.4f}'])
    story.extend([p('Table S2. Fixed-origin logistic controls','Heading1'),tab(rows,[75,250,90,90]),p('C=1, liblinear, maximum 2,000 iterations; train-fitted positional one-hot raw encoder and numeric scaler; validation-MCC threshold grid. DECLARE and the re-ranked controls share at-risk training IDs and eventual-purchase labels, absolute support-gap ranking, support >=20 and <=n-20, empirical-column deduplication, and K=10. The original frozen learned basis has historical fitting/ranking provenance and is shown separately. Its candidate generation is not matched to template enumeration. Electronics has only four usable distinct learned columns, so its K=10 re-ranked arm is unavailable; no fabricated replacement features are inserted.')])
    draft='--draft' in sys.argv
    if draft:
        source=pd.DataFrame();diff=pd.DataFrame();story.append(p('DRAFT: basis-source results pending; no values substituted.','Heading2'))
    else:
        source=pd.read_csv(HERE/'cosmetics_source/comparison/metrics.csv');diff=pd.read_csv(HERE/'cosmetics_source/comparison/paired_differences.csv')
    story.extend([p('Table S3. Cosmetics basis-source control','Heading2'),tab([['Basis','MCC','AP']]+[[r.condition,f'{r.MCC:.4f}',f'{r.AP:.4f}'] for r in source.itertuples()],[325,90,90]),tab([['Pre-purchase minus frozen','Difference','Paired 95% CI']]+[[r.metric,f'{r.delta:+.4f}',f'[{r.lower95:+.4f}, {r.upper95:+.4f}]'] for r in diff.itertuples()],[220,100,185]),p('New learning preserves the replayed original fitting/ranking IDs where a nonempty pre-purchase trace exists: 9,955 fitting and 7,544 ranking histories. Respectively 45 and 21 positive empty histories are excluded without replacement. Both formula targets remain eventual purchase; the new source is truncated at first purchase, then restricted to its last 20 events. K=10, seed 42, depth 10, 60 epochs, batch 100, learning rate 0.01, one restart and maximum 300 candidates follow the recovered settings. The final cleanup ranks all substantive candidates by balanced accuracy, signed support gap and positive support, removes duplicate formula strings, then takes ten. The source control independently refits both models; its frozen result differs slightly from Table S2 under single-thread execution. The main basis is not changed. The original sample-CSV IDs do not match actual learner inputs; trace-order-matching replayed IDs are used.'),PageBreak()])
    formulas=pd.read_csv(HERE/'audit/all_formulas.csv');support=pd.read_csv(HERE/'audit/formula_support.csv')
    for ds in ['Coveo','Electronics','Cosmetics']:
        story.append(p('Table S4'+{'Coveo':'a','Electronics':'b','Cosmetics':'c'}[ds]+'. '+ds+' frozen formulas','Heading1'))
        story.append(p('All temporal operators use finite-trace semantics and strong next. Rates are conditional on next-10 purchase labels in the first-10-event training/validation cohorts. AST length counts operators and atom/constant occurrences. Full provenance and pairwise counterexamples are supplied as machine-readable files.'))
        for r in formulas[formulas.dataset==ds].itertuples():
            ss=support[(support.dataset==ds)&(support.formula_index==r.index)]
            rates='; '.join(f'{x.split}: + {x.positive_rate:.3f}, - {x.negative_rate:.3f}' for x in ss.itertuples())
            story.append(KeepTogether([p(f'{r.index:02d}. {r.original}','FormulaHeading'),p('Finite-trace form: '+r.simplified),p(r.meaning),p(f'Atoms: {r.atoms}. Nodes: {r.ast_nodes} -> {r.simplified_nodes}. Operators: {r.temporal_operators}. {rates}')]))
        story.append(PageBreak())
    story.extend([p('Semantics, provenance, and scope','Heading1'),p('Table S5. Explicit template definitions','Heading2'),tab([['Family','LTLf definition','Vacuity / boundary'],['Existence','F a','False if a never occurs.'],['Response','G(a -> F b)','True if a never occurs; b at the same event is allowed.'],['Strict precedence','G(!b) OR (!b U (a AND !b))','True if b never occurs; an earlier a is required, not simultaneous a,b.'],['Chain response','G(a -> X b)','True if a never occurs; an a at the last event violates the constraint.']],[85,200,220]),p('These four template families are a small DECLARE-style baseline, not a complete reproduction of all configurations of prior DECLARE encoding work. The comparison tests explicit temporal features; it does not attribute any improvement solely to automatic formula discovery.'),p('Vocabulary','Heading2'),p('b: browsing; d: detail/view; a: add to cart; r: remove from cart. fp/rp: first/revisited product. sp/pc: same/changed product relative to the preceding eligible product-bearing event (Coveo/Cosmetics), or preceding event (Electronics). sc/cc/rc: same/changed/revisited category. hp/np and hc: product present/absent and category present (Cosmetics). In Electronics p2/p3 mean at least two/three distinct products seen; in Cosmetics p2/p3 mean at least two/three occurrences of the current product. Cosmetics dp1/dp2/dp3 encode one/two/at least three distinct products. Dataset-specific abstraction code remains authoritative.'),p('Interpretation limits','Heading2'),p('All 135 within-dataset formula pairs are logically distinguishable on unrestricted finite multi-proposition traces; finite witnesses are saved and checked. Nevertheless, several columns coincide on the observed prefixes. Cosmetics X(hp) is constant on train/validation. Electronics ten learned coordinates reduce to four usable distinct training columns under the prespecified filter. Coveo formula 3 simplifies exactly to F X X a and formula 7 to F X X X a. These are delayed-occurrence conditions, not evidence that a classifier learned complex long-range dependencies.'),p('Source and cost boundaries','Heading2'),p('Coveo protects 20,000 replayed formula-pool sessions inside training. Electronics uses a reconstructed 8,000-session training pool; exact historical split-file identity remains unverified, and the original evaluation includes train/test user overlap. Cosmetics formulas used 526 fitting and 259 ranking histories extending beyond first purchase, while test sessions/users were outside those pools. Supervised purchase labels are legitimate targets; historical-source transfer is distinguished from test contamination.'),p('The audited Full-raw code already trims to dynamic per-batch widths. The published inference timer includes parsing loaded fields, packing, summary construction, transfers and model inference; it excludes disk I/O, upstream abstraction, model loading and formula learning. Historical neural-update savings are not overall training speedups. New feature timings distinguish parsing, counts, all-candidate transitions and formula checks; they are not selected-K=10 latency benchmarks. Some new neural and formula-learning runs overlap, so their wall times are execution records rather than controlled speed comparisons.'),p('The new CPU Cosmetics run records 1,278.33 seconds of learner training and 1,304.24 seconds through initial interpretation/ranking and serialization. The subsequent final cleanup is outside this timer. These are execution records on this machine, not controlled hardware comparisons. Stage-specific feature and neural timing CSVs are included separately.'),p('References: De Giacomo and Vardi (2013), https://www.cs.rice.edu/~vardi/papers/ijcai13.pdf ; Di Francescomarino et al. (2022), https://ceur-ws.org/Vol-3310/paper9.pdf')])
    story.extend([PageBreak(),p('Retained horizon sensitivity','Heading1'),Image(str(PROJECT/'work/paper_thematic/source/figures/rq3_horizon.pdf').replace('.pdf','.png'),width=505,height=270),p('Figure S2. Previously reported logistic horizon sensitivity, retained from the recovered manuscript source. It uses the original frozen transition selection, which did not apply the new empirical-column deduplication used in the template control. The displayed uncertainty follows the previous figure (bootstrap SE), not the 95% intervals of Figure S1. No new horizon search was performed.')])
    SimpleDocTemplate(str(out/('experiment_supplement_draft.pdf' if draft else 'experiment_supplement.pdf')),pagesize=(595.28,841.89),leftMargin=42,rightMargin=42,topMargin=36,bottomMargin=40).build(story,onFirstPage=page,onLaterPages=page)
if __name__=='__main__':main()
